// Staff-only document. Never copy into public assets; serve only after staff authentication.
// Source: Treehouse-Budtender-App-SOP.pdf, October 6, 2026, discount-only notes revision.
const pdf = '';
export function staffGuideResponse() {
  const bytes = Uint8Array.from(atob(pdf), c => c.charCodeAt(0));
  return new Response(bytes, { headers: {
    "Content-Type": "application/pdf",
    "Content-Disposition": 'inline; filename="Treehouse-Budtender-App-SOP.pdf"',
    "Cache-Control": "private, no-store",
    "X-Content-Type-Options": "nosniff",
    "X-Robots-Tag": "noindex, nofollow, noarchive"
  } });
}
